        "deposit.kbk.text": "\u5982\u679c\u60a8\u662f\u5409\u5c14\u5409\u65af\u65af\u5766\u5546\u4e1a\u94f6\u884c\u7684\u5ba2\u6237\uff0c\u60a8\u53ef\u4ee5\u4f7f\u7528\u8be5\u7f51\u7ad9\u6216\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u7eed\u4ea4\u201cBuleto\u201d\u7684\u5e10\u6237\u800c\u65e0\u9700\u4efb\u4f55\u624b\u7eed\u8d39\uff01<br/>\u4e3a\u6b64\uff0c\u8bf7\u8f6c\u81f3\u201c\u4ea4\u6613 - \u5b9a\u671f\u4ed8\u6b3e - \u91d1\u878d\u670d\u52a1 - Buleto\u201d\u90e8\u5206\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7 <b>{accountNumber}<b>\uff0c\u4ed8\u6b3e\u91d1\u989d\uff0c\u7136\u540e\u70b9\u51fb\u201c\u7ee7\u7eed\u201d\u3002 <br/>\u5173\u4e8e\u5409\u5c14\u5409\u65af\u65af\u5766\u5546\u4e1a\u94f6\u884c\u7684\u4e92\u8054\u7f51\u548c\u624b\u673a\u94f6\u884c\u7684\u66f4\u591a\u4fe1\u606f\uff0c\u8bf7\u53c2\u9605<a href='http://www.cbk.kg/'> cbk.kg </a>",
        "deposit.mobilnik.name": "\u7535\u5b50\u94b1\u5305\u201c\u624b\u673a\u94b1\u201d",
        "deposit.mobilnik.amount": "\u624b\u7eed\u8d39",
        "deposit.mobilnik.text": "\u4f7f\u7528\u201c\u624b\u673a\u94b1\u201d\u7f51\u7ad9\u6216\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u7eed\u4ea4\u201cBuleto\u201d\u8d26\u6237\u800c\u65e0\u9700\u4efb\u4f55\u624b\u7eed\u8d39\uff01 <br/>\u4e3a\u6b64\uff0c\u8bf7\u8f6c\u5230\u201c\u7535\u5b50\u94b1\u5305 - \u5176\u4ed6\u670d\u52a1 - Buleto\u201d\u90e8\u5206\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7 <b>{accountNumber}<b>\uff0c\u4ed8\u6b3e\u91d1\u989d\u5e76\u70b9\u51fb\u201c\u652f\u4ed8\u201d\u3002<br/>  \u5728\u201c\u624b\u673a\u94b1\u201d\u652f\u4ed8\u670d\u52a1\u7684\u5e2e\u52a9\u4e0b\uff0c\u60a8\u53ef\u4ee5\u652f\u4ed8\u5176\u4ed6\u670d\u52a1\uff0c\u5c06\u8d44\u91d1\u63d0\u53d6\u5230\u94f6\u884c\u8d26\u6237\u5e76\u5151\u73b0\u3002\u5173\u4e8e \u201c\u624b\u673a\u94b1\u201d\u7535\u5b50\u94b1\u5305\u7684\u66f4\u591a\u4fe1\u606f\uff0c\u8bf7\u53c2\u9605<a href='https://www.mobilnik.kg/'> mobilnik.kg </a>",
        "deposit.unipay.name": "\u652f\u4ed8\u7d42\u7aef\u201cUnipay\u201d",
        "deposit.unipay.amount": "\u4f63\u91d1 \u2014 2%",
