        "deposit.opex.desc": "\u60a8\u53ef\u4ee5\u901a\u8fc7\u4e24\u79cd\u65b9\u5f0f\u8d2d\u4e70 Opex \u52a0\u5bc6\u8d27\u5e01\u652f\u7968\uff0c\u65e0\u9700\u4f63\u91d1\uff1a",
        "deposit.opex.desc_1": " <b> 1. \u5728Unipay\u6536\u94f6\u53f0 </b> <br /> <br /> \u4f20\u9012\u6536\u94f6\u5458\u6240\u9700\u7684\u91d1\u989d\uff0c\u5e76\u544a\u8bc9\u60a8\u7684\u624b\u673a\u53f7\u7801 Opex \u52a0\u5bc6\u8d27\u5e01\u652f\u7968\u5c06\u53d1\u9001\u5230\u54ea\u91cc\u3002",
        "deposit.opex.desc_2": " <b> 2\u3001\u81ea\u52a9\u652f\u4ed8\u7ec8\u7aefUnipay </b> <br /> <br /> \u5728\u4fe1\u606f\u4ead\u7684\u4e3b\u5c4f\u5e55\u4e0a\uff0c",
        "deposit.opex.desc_2_1": "\u5355\u51fb Bironex \u6309\u94ae",
        "deposit.opex.desc_2_2": "\uff0c\u7136\u540e\u9009\u62e9 OPX\u3001\u8d2d\u4e70\u3002 \u63a5\u4e0b\u6765\u8f93\u5165\u5c06\u901a\u8fc7\u77ed\u4fe1\u53d1\u9001\u52a0\u5bc6\u652f\u7968\u7684\u624b\u673a\u53f7\u7801\u3002 \u63a5\u4e0b\u6765\u586b\u5199\u4e2a\u4eba\u6570\u636e\uff08\u4ec5\u9700\u8981\u4e00\u6b21\uff09\u3002 \u7136\u540e\u63d2\u5165\u7eb8\u5e01\u5e76\u6309\u652f\u4ed8\u6309\u94ae\u3002",
        "deposit.opex.text_1": "\u60a8\u53ef\u4ee5\u4f7f\u7528 Opex \u52a0\u5bc6\u8d27\u5e01\u8fdb\u884c\u5b58\u6b3e\u548c\u53d6\u6b3e\uff0c\u65e0\u9700\u4f63\u91d1\uff01 \u6c47\u7387 1 OPX = 1 \u56fd\u5bb6\u8d27\u5e01<br/>\u8d2d\u4e70\u548c\u51fa\u552e Opex \u6709\u4e24\u79cd\u65b9\u5f0f\uff1a",
        "deposit.opex.text_2": "<b>1.\u201c\u94f6\u8054\u201d\u6536\u94f6\u53f0</b><br/><b>\u8d2d\u4e70\u8fd0\u8425\u652f\u51fa</b><br/>\u5c06\u6240\u9700\u91d1\u989d\u4f20\u9012\u7ed9\u6536\u94f6\u5458\uff0c\u5e76\u544a\u77e5\u60a8\u7684\u624b\u673a\u53f7\u7801\uff0cOpex \u652f\u7968\u53f7\u7801\u5c06\u901a\u8fc7\u77ed\u4fe1\u53d1\u9001\u5230\u8be5\u624b\u673a\u53f7\u7801\u3002 \u7136\u540e\u5728\u7f51\u7ad9\u7684\u201c\u5b58\u6b3e\u201d\u90e8\u5206\u8f93\u5165\u652f\u7968\u53f7\u7801\u3002<br/><b>\u5151\u73b0\u8fd0\u8425\u652f\u51fa</b><br/>\u5728\u7f51\u7ad9\u7684\u201c\u63d0\u6b3e\u201d\u90e8\u5206\u521b\u5efa\u63d0\u6b3e\u8bf7\u6c42\u3002 \u8f93\u5165\u5c06\u901a\u8fc7\u77ed\u4fe1\u53d1\u9001 Opex \u68c0\u67e5\u53f7\u7801\u7684\u624b\u673a\u53f7\u7801\u3002 \u63a5\u4e0b\u6765\uff0c\u8f93\u5165\u4ea4\u6613\u8d26\u6237\u7684\u91d1\u989d\u548c\u5bc6\u7801\u3002 \u5728\u6536\u94f6\u53f0\u5411\u6536\u94f6\u5458\u51fa\u793a\u60a8\u7684\u8eab\u4efd\u8bc1\u4ef6\uff0c\u5e76\u901a\u8fc7\u77ed\u4fe1\u544a\u77e5\u652f\u7968\u53f7\u7801\u3002",
        "deposit.opex.text_3": "<b>2. \u81ea\u52a9\u7f34\u8d39\u673a\u201cUnipay\u201d</b><br/><b>\u8d2d\u4e70\u8fd0\u8425\u652f\u51fa</b><br/>\u5728\u4fe1\u606f\u4ead\u7684\u4e3b\u5c4f\u5e55\u4e0a\uff0c",
        "deposit.opex.text_3_1": "\u5355\u51fb\u201cBironex\u201d\u6309\u94ae",
        "deposit.opex.text_3_2": "\uff0c\u7136\u540e\u9009\u62e9\u201cOPX\u201d\u3001\u201c\u8d2d\u4e70\u201d\u3002 \u63a5\u4e0b\u6765\u8f93\u5165\u5c06\u901a\u8fc7\u77ed\u4fe1\u53d1\u9001 Opex \u652f\u7968\u7684\u624b\u673a\u53f7\u7801\u3002 \u63a5\u4e0b\u6765\u586b\u5199\u4e2a\u4eba\u6570\u636e\uff08\u4ec5\u9700\u8981\u4e00\u6b21\uff09\u3002 \u7136\u540e\u63d2\u5165\u7eb8\u5e01\u5e76\u6309\u201c\u4ed8\u6b3e\u201d\u3002<br/><b>\u5151\u73b0\u8fd0\u8425\u652f\u51fa</b><br/>\u5728\u7f51\u7ad9\u7684\u201c\u63d0\u6b3e\u201d\u90e8\u5206\u521b\u5efa\u63d0\u6b3e\u8bf7\u6c42\u3002 \u8f93\u5165\u5c06\u53d1\u9001\u5305\u542b Opex \u68c0\u67e5\u7684\u77ed\u4fe1\u7684\u624b\u673a\u53f7\u7801\u3002 \u63a5\u4e0b\u6765\uff0c\u5728 Unipay kiosk \u7684\u4e3b\u5c4f\u5e55\u4e0a",
        "deposit.opex.text_3_2_1": "\uff0c\u5355\u51fb Bironex \u6309\u94ae",
        "deposit.opex.text_3_2_2": "\uff0c\u7136\u540e\u9009\u62e9 OPX\u3001\u51fa\u552e\u3002 \u7136\u540e\u60a8\u9700\u8981\u8f93\u5165\u4e2a\u4eba\u6570\u636e\uff08\u4ec5\u9700\u8981\u4e00\u6b21\uff09\u3002 \u4e4b\u540e\uff0c\u5728\u201c\u53d1\u884c\u4ee3\u7801\u201d\u5b57\u6bb5\u4e2d\u8f93\u5165\u652f\u7968\u53f7\u7801\u5e76\u63a5\u6536\u8d44\u91d1\u3002",
