        "landing.how_it_works.col_1_title": "\u8bf7\u7eed\u4ea4\u8d26\u6237",
        "landing.how_it_works.col_1_text": "\u901a\u8fc7\u5feb\u901f\u6ce8\u518c\u5e76\u91c7\u7528\u4ee5\u60a8\u65b9\u4fbf\u7684\u65b9\u5f0f\u6765\u7eed\u4ea4\u4ea4\u6613\u8d26\u6237",
