        "landing.how_it_works.col_2_text": "\u4ea4\u6613\u4efb\u4f55\u8d44\u4ea7\uff0c80\u79d2\u4e4b\u5185\u8d5a\u53d6\u9ad8\u8fbe\u76843600%\u7684\u5229\u6da6\uff0c\u6700\u4f4e\u6295\u8d44\u4e3a10 \u0423.E.\u7d22\u59c6",
        "landing.how_it_works.col_3_title": "\u8d5a\u53d6\u5229\u6da6",
        "landing.how_it_works.col_3_text": "\u53ef\u4ee5\u4f7f\u7528\u6d41\u884c\u7684\u52a0\u5bc6\u8d27\u5e01\u7acb\u5373\u63d0\u53d6\u8d44\u91d1",
        "landing.how_to_sell.title": "\u5982\u4f55\u8fdb\u884c\u4ea4\u6613\uff1f",
        "landing.how_to_sell.sub_title": "\u786e\u5b9a\u4ef7\u683c\u5c06\u4e0a\u6da8\u6216\u4e0b\u8dcc",
        "landing.how_to_sell.paragraph_1": "\u9009\u62e9\u8d44\u4ea7\u548c\u6295\u8d44\u91d1\u989d\uff0c\u786e\u5b9a\u8d44\u4ea7\u4ef7\u683c\u4e0a\u6da8\u6216\u4e0b\u8dcc\uff0c\u7136\u540e\u70b9\u51fb\u201c\u4e0a\u65b9\u201d\u6216\u201c\u4e0b\u65b9\u201d\u3002",
        "landing.how_to_sell.paragraph_2": "\u53ea\u9700\u505a\u51fa\u9884\u6d4b - \u8d27\u5e01\u5bf9\u7684\u6c47\u7387\u5c06\u4f1a\u4e0a\u6da8\u6216\u4e0b\u8dcc\uff0c\u4f8b\u5982\u6b27\u5143/\u7f8e\u5143\uff08EUR / USD\uff09\u3002",
        "landing.how_to_sell.paragraph_3": "\u6b63\u786e\u7684\u9884\u6d4b\u5c06\u4f7f\u8d5a\u94b1\uff01",
        "landing.how_to_sell.button": "\u5f00\u7acb\u8d26\u6237",
        "landing.cryptocurrency.title": "\u52a0\u5bc6\u8d27\u5e01",
        "landing.cryptocurrency.sub_title": "\u91c7\u7528\u52a0\u5bc6\u8d27\u5e01\u6c47\u7387\u8d5a\u94b1-\u5f88\u7b80\u5355\uff01",
        "landing.cryptocurrency.paragraph_1": "\u5728\u6211\u4eec\u7684\u5e73\u53f0\u4e0a\uff0c\u67098\u4e2a\u6d41\u884c\u7684\u5bc6\u7801\u8d27\u5e01\u5bf9\u3002",
