        "landing.sell_forex.paragraph": "\u5feb\u901f\u6ce8\u518c\u3001\u8bad\u7ec3\u8d26\u6237\u300110\u7d22\u59c6\u4ee5\u4e0a\u7684\u5b58\u6b3e\uff0c\u8d85\u8fc7140\u4e2a\u4ea4\u6613\u5de5\u5177\u3002",
        "landing.sell_forex.button": "\u5f00\u59cb\u8d38\u6613",
        start_title: "\u5f00\u59cb\u8d38\u6613",
        "landing.app.title": "Buleto \u968f\u65f6\u5728\u8eab\u8fb9\uff01",
        "landing.app.paragraph": "Buleto\u4ea4\u6613\u5e73\u53f0\u968f\u65f6\u53ef\u7528\u4e8e\u60a8\u6700\u559c\u7231\u7684\u79fb\u52a8\u8bbe\u5907\u3002 \u53ea\u9700\u6253\u5f00buleto.com\u6216\u5b89\u88c5\u9002\u7528\u4e8eiOS\u548cAndroid\u7684Buleto\u5e94\u7528\u7a0b\u5e8f\uff0c\u5e76\u968f\u65f6\u968f\u5730\u83b7\u5f97\u6536\u5165",
        "landing.title": "\u4ec0\u4e48\u662f\u4e8c\u5143\u671f\u6743\uff1f",
        "landing.paragraph_1": "\u4e8c\u5143\u671f\u6743\u662f\u7531\u60a8\u9009\u62e9\u7684\u8d44\u4ea7\u7684\u7535\u5b50\u5408\u7ea6\u3002 \u5bf9\u4e8e\u4ea4\u6613\uff0c\u60a8\u53ef\u4ee5\u4f7f\u7528\u8d27\u5e01\u5bf9\u3001\u80a1\u7968\u6307\u6570\u3001\u80a1\u6307\u548c\u5546\u54c1\u3002",
        "landing.paragraph_2": "\u6240\u6709\u7684\u4ea4\u6613\u90fd\u5230\u89c2\u5bdf\u724c\u4ef7\u8d70\u52bf\u56fe\uff0c\u5e76\u786e\u5b9a\u4ef7\u683c\u53d8\u52a8\u7684\u65b9\u5411\u3002\u975e\u5e38\u91cd\u8981\u6b63\u786e\u7684\u9884\u6d4b\uff0c\u4ece\u8d2d\u4e70\u4e8c\u5143\u671f\u6743\u5230\u6267\u884c\u65f6\u523b\u7684\u8d44\u4ea7\u5e02\u573a\u4ef7\u683c\u589e\u52a0\u6216\u51cf\u5c11\u3002 \u7c7b\u4f3c\u4ea4\u6613\u4ea4\u6613\u8005\u7ecf\u5e38\u79f0\u4e3a\u201c\u4e0a\u6da8/\u4e0b\u8dcc\u201d\uff0c\u56e0\u4e3a\u9700\u8981\u5728\u4ef7\u683c\u7684\u589e\u957f\u548c\u4e0b\u8dcc\u4e4b\u95f4\u505a\u51fa\u9009\u62e9\u3002",
        "landing.paragraph_3": "\u7528\u4e8c\u5143\u671f\u6743\u8fdb\u884c\u4ea4\u6613\u4e0d\u4ec5\u662f\u6709\u7ecf\u9a8c\u7684\u4e13\u4e1a\u4eba\u5458\uff0c\u8fd8\u521d\u5b66\u8005\u4e5f\u53ef\u8fdb\u884c\u4ea4\u6613\u3002 \u56e0\u6b64\uff0c\u5bf9\u4e8e\u5f88\u591a\u4eba\u6765\u8bf4\uff0c\u5728\u5404\u79cd\u91d1\u878d\u5e02\u573a\u4e0a\u5de5\u4f5c\u7684\u65b9\u5f0f\u90fd\u662f\u4ece\u4e8c\u5143\u671f\u6743\u5f00\u59cb\u7684\u3002",
        "landing.paragraph_4": "Buleto\u5728\u73b0\u4ee3\u548c\u8212\u9002\u7684\u6bd4\u4ec0\u51ef\u514b\u5728\u4ea4\u6613\u5927\u5ef3\u5bf9\u521d\u5b66\u8005\u548c\u9ad8\u7ea7\u4ea4\u6613\u8005\u63d0\u4f9b\u4e2a\u4eba\u548c\u514d\u8d39\u57f9\u8bad\u670d\u52a1\u3002",
        "landing.button": "\u62a5\u540d\u57f9\u8bad",
        "locations.title": "\u201cBuleto\u201d\u5728\u5409\u5c14\u5409\u65af\u65af\u5766\u7684\u7ecf\u7eaa\u5927\u5385\u548c\u4ff1\u4e50\u90e8",
        "locations.description": "\u201cBuleto\u201d\u5728\u6bd4\u4ec0\u51ef\u514b\u5e02\u7684\u7ecf\u7eaa\u5927\u5385\u548c\u4ea4\u6613\u4ff1\u4e50\u90e8\u7684\u5730\u5740\u3002 \u6211\u4eec24\u5c0f\u65f6\uff0c\u65e0\u5047\u671f\u548c\u5468\u672b\u7ecf\u8425\uff01",
        "locations.heading": "Buleto\u5728\u4ea4\u6613\u5927\u5ef3",
        "locations.subheading": "Buleto\u5728\u4ea4\u6613\u5927\u5ef3",
        "locations.paragraph": "\u201cBuleto\u201d\u7ecf\u7eaa\u516c\u53f8\u4e3a\u5176\u5ba2\u6237\u63d0\u4f9b\u7279\u522b\u914d\u5907\u7684\u8212\u9002\u7ecf\u7eaa\u5ba4\u548c\u4ff1\u4e50\u90e8\u8fdb\u884c\u4ea4\u6613\u7684\u673a\u4f1a\u3002 \u6211\u4eec\u5c06\u5f88\u9ad8\u5174\u968f\u65f6\u5728\u4ee5\u4e0b\u5730\u5740\u4e0e\u60a8\u89c1\u9762\uff1a",
        "locations.item_1": "\u695a\u4f0a\u5927\u8857 52/3\u53f7 <em>(\u5361\u5c14\u5e73\u65af\u514b\u8857\u4ea4\u53c9)</em>",
        "locations.item_2": "\u963f\u6b65\u675c\u62c9\u5408\u66fc\u8bfa\u592b\u8857 182\u53f7 <em>(\u82cf\u7ef4\u57c3\u8857 x \u57fa\u8f85\u8857)</em>",
        "locations.item_3": "\u5df4\u4f0a\u7279\u514b\u82f1\u96c4\u8857 55\u53f7 <em>(\u82cf\u7ef4\u57c3\u8857 x \u9ad8\u5c14\u57fa\u8857)</em>",
        "locations.item_4": "\u548c\u5e73\u5927\u8857 35\u53f7 <em>(\u827e\u5c3c\u8857\u4ea4\u53c9)</em>",
        "locations.item_5": "\u963f\u5b8f\u767d\u8036\u592b\u8857 116a\u53f7 <em>(\u6258\u514b\u6258\u7eb3\u91cc\u8036\u592b\u8857)</em>",
        "locations.item_6": "\u4e1d\u7ef8\u4e4b\u8def\u5927\u8857183\u53f7 <em>(\u5e03\u743c\u5c3c\u8857\u4ea4\u53c9)</em>",
        "operations.replenishment": "\u7eed\u4ea4",
        "operations.withdraw": "\u53d6\u6b3e",
        "operations.data": "\u65e5\u671f",
        "operations.operation": "\u4e1a\u52a1",
        "operations.sum": "\u91d1\u989d",
