        "training.text": 'Buleto\u4e3a\u90a3\u4e9b\u5e0c\u671b\u4e86\u89e3\u671f\u6743\u4ea4\u6613\u548c\u5916\u6c47\u5e02\u573a\u7684\u4eba\u58eb\u63d0\u4f9b\u514d\u8d39\u7684\u4e2a\u4eba\u57f9\u8bad\u3002 \u8bf7\u81f4\u7535<a href="tel:+0312979700">0312 97-97-00</a>\u4e0e\u6211\u4eec\u8054\u7cfb\u4ee5\u5b89\u6392\u65f6\u95f4\u548c\u57f9\u8bad\u5730\u70b9\u3002 \u60a8\u53ef\u4ee5\u4eceBuleto\u4ea4\u6613\u5927\u5385\u5217\u8868\u4e2d\u9884\u5148\u9009\u62e9\u4e00\u4e2a\u65b9\u4fbf\u7684\u573a\u6240\uff1a',
