        "about.title": "\u5173\u4e8eBuleto\u516c\u53f8",
        "about.description": "Buleto\u516c\u53f8\u4e3a\u5916\u6c47\u5e02\u573a\u548c\u4e8c\u5143\u671f\u6743\u4ea4\u6613\u63d0\u4f9b\u4e86\u4e00\u4e2a\u72ec\u7279\u7684\u5e73\u53f0\uff0c\u5e76\u63d0\u4f9b\u5404\u79cd\u91d1\u878d\u8d44\u4ea7\u3002",
        "about.head": "\u5173\u4e8e\u6211\u4eec",
        "about.paragraph_1": "<h4>Buleto\u5411\u5176\u4ea4\u6613\u8005\u63d0\u4f9b\u4e86\u65e0\u9650\u673a\u4f1a</h4>",
        "about.paragraph_2": "<p>Buleto\u662f\u8fc4\u4eca\u4e3a\u6b62\u4ea4\u6613\u4e8c\u5143\u671f\u6743\u7684\u9886\u5148\u5e73\u53f0\u3002\u73b0\u5728\uff0c\u4e8c\u5143\u671f\u6743\u4e5f\u6bd4\u4ee5\u5f80\u53d8\u5f97\u8d8a\u6765\u8d8a\u6d41\u884c\uff0cBuleto\u63d0\u4f9b\u4e86\u826f\u597d\u7684\u5de5\u4f5c\u6761\u4ef6\uff0c\u4ea4\u6613\u5546\u5728\u5b89\u5168\u65b9\u9762\uff0c\u5404\u4e2a\u529f\u80fd\u7684\u53ef\u7528\u6027\uff0c\u6613\u7528\u6027\uff0c\u63d0\u4f9b\u5de5\u5177\u548c\u57f9\u8bad\u3002</p>",
        "about.paragraph_3": "Buleto\u81f4\u529b\u4e8e\u4e3a\u5168\u7403\u79c1\u4eba\u548c\u673a\u6784\u6295\u8d44\u8005\u63d0\u4f9b\u6700\u4f18\u8d28\u7684\u4ea4\u6613\u5e73\u53f0\u3002 Buleto\u5458\u5de5\u51c6\u5907\u5411\u5176\u8d38\u6613\u554624\u5c0f\u65f6\u6ca1\u6709\u4f11\u606f\u65e5\u63d0\u4f9b\u5fc5\u8981\u7684\u534f\u52a9\u548c\u4e13\u4e1a\u7ecf\u7eaa\u4eba\u5728\u6bcf\u4e00\u6b65\u9636\u6bb5\u63d0\u4f9b\u6307\u5bfc\u670d\u52a1\u3002</p>",
        "about.paragraph_4": "<h4>Buleto\u5e73\u53f0\u7684\u4f18\u52bf\uff1a</h4>",
        "about.paragraph_5": "<ol><li>\u76f4\u89c2\u7684Web\u754c\u9762\uff0c</li> <li>\u60a8\u4e0d\u9700\u8981\u4e0b\u8f7d\u548c\u5b89\u88c5\u8f6f\u4ef6</li> <li>\u4e00\u4e2a\u7b80\u5355\u7684\u4ea4\u6613 - \u7b80\u5355\u6613\u61c2\uff0c\u6709\u660e\u786e\u7684\u89e3\u91ca</li> <li>\u5404\u79cd\u4ea7\u54c1</li> <li>\u4e3a\u7528\u6237\u65b9\u4fbf\u7684\u4ea4\u6613\u4e1a\u52a1</li> <li>\u5b89\u5168 - \u98ce\u9669/\u5229\u7387\u5728\u9009\u9879\u660e\u786e\u6307\u51fa</li> <li>\u5feb\u901f\u548c\u7b80\u5355\u7684\u5b58\u6b3e/\u53d6\u6b3e</li></ol>",
        "about.paragraph_6": "<p> Buleto\u4f7f\u547d - \u662f\u5411\u60a8\u4f5c\u4e3a\u4e00\u4e2a\u7ecf\u7eaa\u5546\u63d0\u4f9b\u6700\u5b89\u5168\uff0c\u6700\u4fbf\u6377\uff0c\u6700\u4f73\u8fdb\u884c\u8d38\u6613\u65b9\u5f0f;.\u6211\u4eec\u7684\u5b9a\u4ef7\u548c\u6267\u884c\u6a21\u5757\u4fdd\u8bc1\u4f7f\u7528\u6700\u73b0\u4ee3\u548c\u5148\u8fdb\u7684\u6280\u672f\u3002\uff06nbsp;\u901a\u8fc7\u4e0e\u8def\u900f\u793e\u5408\u4f5c\uff0c\u6211\u4eec\u5f97\u5230\u4e86\u5b9e\u65f6\u51c6\u786e\u7684\u6570\u636e\u6d41\uff0c\u5e76\u5728\u6211\u4eec\u7684\u6761\u6b3e\u660e\u786e\u7684\u89c4\u5b9a\u5b9e\u65f6\u5e02\u573a\u4ef7\u683c\u548c\u80a1\u7968\u671f\u6743\u4e4b\u95f4\u7684\u5dee\u989d&nbsp;\u6211\u4eec\u5728\u4efb\u4f55\u7279\u5b9a\u65f6\u523b\u63d0\u4f9b\u5230\u671f\u65f6\u95f4\u8868\u4ee5\u786e\u4fdd\u4ea4\u6613\u8005\u7684\u5e73\u9759\uff0c\u4ee5\u4fbf\u4ea4\u6613\u8005\u4e0d\u4f1a\u9047\u5230\u4efb\u4f55\u95ee\u9898\u3002 </p>",
        "about.paragraph_7": "<p>\u5ba2\u6237\u8d44\u91d1\u5b58\u50a8\u5728\u4e00\u4e2a\u5355\u72ec\u7684\u8d26\u6237\u4e0a\u3002\u8d26\u6237\u4e0a\u7684\u8d44\u91d1\u4ec5\u7528\u4e8e\u901a\u8fc7\u6211\u4eec\u7684\u7f51\u7ad9\u6839\u636e\u5ba2\u6237\u7533\u8bf7\u8fdb\u884c\u4ea4\u6613\u671f\u6743\uff0c\u5e76\u4e14\u4e0d\u4f1a\u7528\u4e8e\u4efb\u4f55\u5176\u4ed6\u76ee\u7684\u3002\u6211\u4eec\u7684\u4e49\u52a1\u548c\u98ce\u9669\u7ba1\u7406\u7531\u4e13\u4e1a\u4eba\u5458\u8fdb\u884c\uff0c\u6211\u4eec\u4fdd\u8bc1\u6839\u636e\u6211\u4eec\u7684\u6761\u4ef6\u652f\u4ed8\u60a8\u7684\u5229\u6da6\u3002</p>",
        "about.paragraph_8": "<p>\u5728Buleto\u548c\u5176\u5408\u4f5c\u5355\u4f4d\u6709\u751f\u91d1\u878d\u5de5\u5177\u548c\u98ce\u9669\u7ba1\u7406\u9886\u57df\u7684\u4e13\u4e1a\u5916\u6c47\u7ecf\u7eaa\u4e13\u5bb6\u3002\u53e6\u5916\uff0c\u6211\u4eec\u4e0e\u652f\u4ed8\u7cfb\u7edf\u5408\u4f5c\u3002\u6211\u4eec\u5904\u7406\u4ea4\u6613\u4e8c\u5143\u671f\u6743\u7684\u5404\u4e2a\u65b9\u9762\uff0c\u4ee5\u4fbf\u60a8\u83b7\u5f97\u6700\u597d\u7684\u4ea4\u6613\u5370\u8c61\u3002\u5728\u4efb\u4f55\u65f6\u5019\u3002 </p>",
        "about.paragraph_9": "<h4>\u52a0\u5165Buleto\u5e76\u4ee5\u4e13\u4e1a\u4eba\u58eb\u7684\u8eab\u4efd\u8fdb\u884c\u4ea4\u6613\uff01</h4>",
